Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_add_digit_malloc_failure_when_adding_next_digit(void) {
    // Setup: create a valid big_int node (digit is NOT NULL)
    // This requires one allocation to succeed.
    malloc_fail_after(0); // Let the first allocation succeed
    big_int *digit = add_digit(NULL, '5');
    TEST_ASSERT_NOT_NULL(digit);

    // Condition: digit->next_digit is NULL (we haven't added a next digit)
    TEST_ASSERT_NULL(digit->next_digit);

    // Now we want to trigger the path where we try to add a next digit,
    // but the malloc for digit->next_digit fails.
    // The next allocation (the second one) should fail.
    malloc_fail_after(1); // First allocation succeeded, fail the second.

    // Test: call add_digit with a non-NULL digit whose next_digit is NULL.
    // This should attempt to allocate a new node for next_digit, which will fail.
    big_int *result = add_digit(digit, '7');

    // Assertions: should return NULL due to allocation failure.
    TEST_ASSERT_NULL(result);
    // The original digit should still be valid and unchanged.
    TEST_ASSERT_NOT_NULL(digit);
    TEST_ASSERT_EQUAL('5', digit->value);
    TEST_ASSERT_NULL(digit->next_digit);
    // prev_digit should be NULL as it was created as the head.
    TEST_ASSERT_NULL(digit->prev_digit);

    // Cleanup
    if (digit != NULL) {
        helper_free_big_int(digit);
    }
}

