// Asserts that a big_int linked list has the expected number of digits
void assert_big_int_digit_count(big_int *digit, int expected_count) {
    int count = 0;
    big_int *current = digit;
    while (current != NULL) {
        count++;
        current = current->next_digit;
    }
    TEST_ASSERT_EQUAL_INT(expected_count, count);
}

// ========== Created - Utility Operations ==========

// Creates a big_int linked list from an array of digit values
big_int* helper_create_big_int(char *values, int size) {
    big_int *root = NULL;
    big_int *current = NULL;
    for (int i = 0; i < size; i++) {
        if (i == 0) {
            root = add_digit(NULL, values[i]);
            current = root;
        } else {
            current = add_digit(current, values[i]);
        }
    }
    return root;
}

// Frees all digits in a big_int linked list
void helper_free_big_int(big_int *digit) {
    // Call remove_digits with N=0 to free all remaining nodes safely
    // This ensures no double-free if remove_digits already freed some nodes
    if (digit != NULL) {
        (void)remove_digits(digit, 0);
    }
}

